class FormulaTranslator
{
    // A sheet name may be quoted, in which case it can contain periods.
    private const SHEET_NAME = "('(?:[^']|'')*'|[^\.']+)";

    // Skip sheet references that have already been converted, so that periods
    // inside quoted sheet names are not mistaken for address separators.
    private const CONVERTED_SHEET = "'(?:[^']|'')*'(?=!)(*SKIP)(*F)|";

    public static function convertToExcelAddressValue(string $openOfficeAddress): string
    {
        $excelAddress = $openOfficeAddress;

        // Cell range 3-d reference
        // As we don't support 3-d ranges, we're just going to take a quick and dirty approach
        //  and assume that the second worksheet reference is the same as the first
        $excelAddress = (string) preg_replace(
            [
                '/' . self::CONVERTED_SHEET . '\$?' . self::SHEET_NAME . '\.([^\.]+):\$?' . self::SHEET_NAME . '\.([^\.]+)/miu',
                '/' . self::CONVERTED_SHEET . '\$?' . self::SHEET_NAME . '\.([^\.]+):\.([^\.]+)/miu', // Cell range reference in another sheet
                '/' . self::CONVERTED_SHEET . '\$?' . self::SHEET_NAME . '\.([^\.]+)/miu', // Cell reference in another sheet
                '/' . self::CONVERTED_SHEET . '\.([^\.]+):\.([^\.]+)/miu', // Cell range reference
                '/' . self::CONVERTED_SHEET . '\.([^\.]+)/miu', // Simple cell reference
            ],
            [
                '$1!$2:$4',
                '$1!$2:$3',
                '$1!$2',
                '$1:$2',
                '$1',
            ],
            $excelAddress
        );

        return $excelAddress;
    }

